// n8n Code node · "Plan the update" (Run once for all items)
// Turns an action from the app (assign, done, snooze…) into the call each source
// tool needs. The four branches after the Switch execute it (demo mode by default).

const ROSTER = [{"id":"neha","name":"Neha Kapoor","email":"neha@airtribe.example","slack_id":"UNEHA","github_login":"neha-airtribe","role":"Engineering Manager","external":false,"skills":[]},{"id":"rahul","name":"Rahul Verma","email":"rahul@airtribe.example","slack_id":"URAHUL","github_login":"rahul-airtribe","role":"Senior Frontend Engineer","external":false,"skills":["frontend","learner-web","notifications","career"]},{"id":"ananya","name":"Ananya Iyer","email":"ananya@airtribe.example","slack_id":"UANANYA","github_login":"ananya-airtribe","role":"Backend Engineer","external":false,"skills":["backend","grading","payments","api"]},{"id":"karan","name":"Karan Mehta","email":"karan@airtribe.example","slack_id":"UKARAN","github_login":"karan-airtribe","role":"Full-stack Engineer","external":false,"skills":["live-sessions","video","mentor-connect","api"]},{"id":"sneha","name":"Sneha Reddy","email":"sneha@airtribe.example","slack_id":"USNEHA","github_login":"sneha-airtribe","role":"QA Engineer","external":false,"skills":["qa","e2e","release"]},{"id":"arjun","name":"Arjun Nair","email":"arjun@airtribe.example","slack_id":"UARJUN","github_login":"arjun-airtribe","role":"Platform Engineer","external":false,"skills":["infra","payments","security","devops"]},{"id":"meera","name":"Meera Joshi","email":"meera@airtribe.example","slack_id":"UMEERA","github_login":"meera-airtribe","role":"Product Designer","external":false,"skills":["design","copy","career"]},{"id":"vikram","name":"Vikram Rao","email":"vikram@airtribe.example","slack_id":"UVIKRAM","github_login":"vikram-airtribe","role":"Data Engineer","external":false,"skills":["data","analytics","leaderboard"]},{"id":"ishita","name":"Ishita Das","email":"ishita@airtribe.example","slack_id":"UISHITA","github_login":"ishita-airtribe","role":"Program Manager","external":false,"skills":["programs","mentors","learners"]},{"id":"rohan","name":"Rohan Bhatia","email":"rohan@airtribe.example","slack_id":"UROHAN","github_login":"rohan-airtribe","role":"Head of Product","external":true,"skills":[]},{"id":"priya","name":"Priya Menon","email":"priya@airtribe.example","slack_id":"UPRIYA","github_login":"priya-airtribe","role":"Learner Success Lead","external":true,"skills":[]},{"id":"aakash","name":"Aakash Gupta","email":"aakash@airtribe.example","slack_id":"UAAKASH","github_login":"aakash-airtribe","role":"Mentor Lead","external":true,"skills":[]},{"id":"tanvi","name":"Tanvi Shah","email":"tanvi@airtribe.example","slack_id":"UTANVI","github_login":"tanvi-airtribe","role":"Marketing Manager","external":true,"skills":[]},{"id":"kavya","name":"Kavya Pillai","email":"kavya@airtribe.example","slack_id":"UKAVYA","github_login":"kavya-airtribe","role":"Finance Partner","external":true,"skills":[]},{"id":"sameer","name":"Sameer Kulkarni","email":"sameer@talentbridge.example","slack_id":"USAMEER","github_login":"sameer-airtribe","role":"Partnerships, TalentBridge","external":true,"skills":[]},{"id":"dependabot","name":"Dependabot","email":"dependabot@airtribe.example","slack_id":"UDEPENDABOT","github_login":"dependabot[bot]","role":"Automated updates","external":true,"skills":[]},{"id":"ci","name":"Release bot","email":"ci@airtribe.example","slack_id":"UCI","github_login":"airtribe-release-bot","role":"CI/CD","external":true,"skills":[]}];
const body = $('Action from WorkRadar').first().json.body || {};
const ok = ['assign', 'done', 'reopen', 'snooze', 'unsnooze'];
if (!ok.includes(body.action) || !body.itemId) throw new Error('Expected { action, itemId, source, ref }');

const person = ROSTER.find((p) => p.name === body.assignee || p.id === body.assignee);
const ref = body.ref || body.itemId;
const source = ['jira', 'github', 'slack', 'email'].includes(body.source) ? body.source : 'jira';
const when = body.snoozedUntil ? new Date(body.snoozedUntil).toUTCString().slice(0, 22) : '';

const plans = {
  jira: {
    assign: { method: 'PUT', path: `/rest/api/3/issue/${ref}/assignee`, body: { accountId: person ? `jira-${person.id}` : null } },
    done: { method: 'POST', path: `/rest/api/3/issue/${ref}/transitions`, body: { transition: { name: 'Done' } } },
    reopen: { method: 'POST', path: `/rest/api/3/issue/${ref}/transitions`, body: { transition: { name: 'To Do' } } },
    snooze: { method: 'PUT', path: `/rest/api/3/issue/${ref}/properties/workradar.snooze`, body: { until: body.snoozedUntil } },
    unsnooze: { method: 'DELETE', path: `/rest/api/3/issue/${ref}/properties/workradar.snooze` },
  },
  github: {
    assign: { method: 'POST', path: `/repos/{owner}/{repo}/issues/{number}/assignees`, body: { assignees: person ? [person.github_login] : [] } },
    done: { method: 'POST', path: `/repos/{owner}/{repo}/issues/{number}/labels`, body: { labels: ['workradar:done'] } },
    reopen: { method: 'DELETE', path: `/repos/{owner}/{repo}/issues/{number}/labels/workradar:done` },
    snooze: { method: 'POST', path: `/repos/{owner}/{repo}/issues/{number}/labels`, body: { labels: ['workradar:snoozed'] } },
    unsnooze: { method: 'DELETE', path: `/repos/{owner}/{repo}/issues/{number}/labels/workradar:snoozed` },
  },
  slack: {
    assign: { method: 'POST', path: '/api/chat.postMessage', body: { thread_ts: '{thread}', text: `${person ? `<@${person.slack_id}>` : 'Someone'} is now the owner (assigned in WorkRadar).` } },
    done: { method: 'POST', path: '/api/reactions.add', body: { name: 'white_check_mark' } },
    reopen: { method: 'POST', path: '/api/reactions.remove', body: { name: 'white_check_mark' } },
    snooze: { method: 'POST', path: '/api/reminders.add', body: { text: `Follow up on ${ref}`, time: body.snoozedUntil } },
    unsnooze: { method: 'POST', path: '/api/reminders.delete', body: {} },
  },
  email: {
    assign: { method: 'POST', path: '/gmail/v1/users/me/messages/{id}/forward', body: { to: person ? person.email : null } },
    done: { method: 'POST', path: '/gmail/v1/users/me/messages/{id}/modify', body: { removeLabelIds: ['INBOX'], addLabelIds: ['WorkRadar/Done'] } },
    reopen: { method: 'POST', path: '/gmail/v1/users/me/messages/{id}/modify', body: { addLabelIds: ['INBOX'], removeLabelIds: ['WorkRadar/Done'] } },
    snooze: { method: 'POST', path: '/gmail/v1/users/me/messages/{id}/modify', body: { addLabelIds: ['WorkRadar/Snoozed'], removeLabelIds: ['INBOX'] } },
    unsnooze: { method: 'POST', path: '/gmail/v1/users/me/messages/{id}/modify', body: { addLabelIds: ['INBOX'], removeLabelIds: ['WorkRadar/Snoozed'] } },
  },
};

const verb = { assign: `Assigned ${ref} to ${person ? person.name.split(' ')[0] : 'a teammate'}`, done: `Marked ${ref} done`, reopen: `Reopened ${ref}`, snooze: `Snoozed ${ref} until ${when}`, unsnooze: `Brought ${ref} back` }[body.action];
const toolName = { jira: 'Jira', github: 'GitHub', slack: 'Slack', email: 'Gmail' }[source];

return [
  {
    json: {
      ...body,
      source,
      tool: toolName,
      call: plans[source][body.action],
      notify: body.action === 'assign' && person ? { slackUser: person.slack_id, text: `Neha assigned you ${ref}: ${body.title || ''}` } : null,
      summary: verb,
    },
  },
];

// n8n Code node · "<Tool>: apply" (Run once for all items)
// Demo mode: records the call it would make. To go live, replace this node with the
// native Jira / GitHub / Slack / Gmail node (or an HTTP Request node) using the
// "call" field prepared by "Plan the update".

const a = $input.first().json;
const live = $('Config').first().json.liveMode === true;
return [
  {
    json: {
      ok: true,
      message: live ? `${a.summary}. Synced to ${a.tool} via n8n.` : `${a.summary}. n8n prepared the ${a.tool} update (demo mode).`,
      tool: a.tool,
      call: a.call,
      notify: a.notify,
      at: new Date().toISOString(),
    },
  },
];

